import subprocess, math, re
BIN="./executable"
a=6378137.0; e2=0.00669438002290; e=math.sqrt(e2)
def W(phi):
    s=math.sin(phi); return math.sqrt(1-e2*s*s)
def asinh(x): return math.asinh(x)
def psi(phi):
    s=math.sin(phi); return math.asinh(math.tan(phi)) - e*math.atanh(e*s)
def meridian(phi):
    c1=1-e2/4-3*e2**2/64-5*e2**3/256
    c2=3*e2/8+3*e2**2/32+45*e2**3/1024
    c3=15*e2**2/256+45*e2**3/1024
    c4=35*e2**3/3072
    return a*(c1*phi - c2*math.sin(2*phi) + c3*math.sin(4*phi) - c4*math.sin(6*phi))
def q2(phi):
    s=math.sin(phi)
    return (1-e2)/2*(s/(1-e2*s*s) + math.atanh(e*s)/e)
def run(args, inp):
    p=subprocess.run([BIN]+args, input=inp.encode(), capture_output=True); return p.stdout.decode(),p.stderr.decode()
PROJ={
 'merc': (lambda lam,phi:(a*lam, a*psi(phi)), 1),
 'sinu': (lambda lam,phi:(a*lam*math.cos(phi)/W(phi), meridian(phi)), 1),
 'cea':  (lambda lam,phi:(a*lam, a*q2(phi)), 1),
 'eqc':  (lambda lam,phi:(a*lam, meridian(phi)), 1),
 'mill': (lambda lam,phi:(a*lam, a*1.25*math.log(math.tan(math.pi/4+0.4*phi))), 0),
}
def factors(proj, lam, phi, delta=1e-5, mode='c'):
    f,ellip=PROJ[proj]
    def F(l,p): x,y=f(l,p); return x,y
    if mode=='c':
        xl=(F(lam+delta,phi)[0]-F(lam-delta,phi)[0])/(2*delta)
        yl=(F(lam+delta,phi)[1]-F(lam-delta,phi)[1])/(2*delta)
        xp=(F(lam,phi+delta)[0]-F(lam,phi-delta)[0])/(2*delta)
        yp=(F(lam,phi+delta)[1]-F(lam,phi-delta)[1])/(2*delta)
    else:
        xl=(F(lam+delta,phi)[0]-F(lam,phi)[0])/delta
        yl=(F(lam+delta,phi)[1]-F(lam,phi)[1])/delta
        xp=(F(lam,phi+delta)[0]-F(lam,phi)[0])/delta
        yp=(F(lam,phi+delta)[1]-F(lam,phi)[1])/delta
    if ellip:
        rho=a*(1-e2)/W(phi)**3; nu=a*math.cos(phi)/W(phi)
    else:
        rho=a; nu=a*math.cos(phi)
    h=math.hypot(xp,yp)/rho
    k=math.hypot(xl,yl)/nu
    s=abs(xl*yp-xp*yl)/(rho*nu)
    # angles
    th_p=math.atan2(xp,yp)      # meridian angle from north
    th_l=math.atan2(xl,yl)      # parallel angle from north
    conv=math.degrees(th_p)     # convergence?
    theta=90.0-math.degrees(th_p)+math.degrees(th_l)
    w=math.degrees(math.asin(abs(math.sin(th_p-th_l))))
    # tissot
    ap=(h+k)/2; ab=math.sqrt(abs(h*h-k*k))/2
    am=math.hypot(ap,ab) if False else None
    return h,k,s,theta,conv,w,ap+ab,ap-ab
def getobs(proj,l,ph,extra=[]):
    out,err=run(["+proj="+proj]+extra+["-V"], "%s %s\n"%(l,ph))
    o={}
    for line in out.split("\n"):
        for key,pat in [('h','Meridian scale \\(h\\) : ([-\\d.e+]+)  \\( (.*) % error \\)'),('k','Parallel scale \\(k\\) : ([-\\d.e+]+)  \\( (.*) % error \\)'),
                        ('s','Areal scale \\(s\\):\\s+([-\\d.e+]+)  \\( (.*) % error \\)'),('w','Angular distortion \\(w\\): ([-\\d.e+]+)'),
                        ('theta','Meridian/Parallel angle: ([-\\d.e+]+)'),('conv','Convergence : \\S+ \\[ ([-\\d.e+]+) \\]'),
                        ('ab','Max-min \\(Tissot axis a-b\\) scale error: ([-\\d.e+]+) ([-\\d.e+]+)')]:
            m=re.match(pat,line)
            if m:
                if key=='ab': o['a']=float(m.group(1)); o['b']=float(m.group(2))
                else: o[key]=float(m.group(1))
    return o
for proj in ['merc','sinu','cea','eqc','mill']:
    for (l,ph) in [(2,49),(30,60),(0,0),(10,20)]:
        o=getobs(proj,l,ph)
        m=factors(proj, math.radians(l), math.radians(ph))
        print("%-5s (%3d,%3d) obs h=%-12s k=%-12s s=%-12s th=%-10s conv=%-12s w=%-8s a=%s b=%s"%(proj,l,ph,o.get('h'),o.get('k'),o.get('s'),o.get('theta'),o.get('conv'),o.get('w'),o.get('a'),o.get('b')))
        print("      calc h=%.8f k=%.8f s=%.8f th=%.6f conv=%.8f w=%.4f a=%.6f b=%.6f"%m)
PYEOF
