def factors(proj, lam, phi, delta=1e-5, mode='c'):
    f,ellip=PROJ[proj]
    def F(l,p): x,y=f(l,p); return x,y
    if mode=='c':
        xl=(F(lam+delta,phi)[0]-F(lam-delta,phi)[0])/(2*delta)
        yl=(F(lam+delta,phi)[1]-F(lam-delta,phi)[1])/(2*delta)
        xp=(F(lam,phi+delta)[0]-F(lam,phi-delta)[0])/(2*delta)
        yp=(F(lam,phi+delta)[1]-F(lam,phi-delta)[1])/(2*delta)
    else:
        xl=(F(lam+delta,phi)[0]-F(lam,phi)[0])/delta
        yl=(F(lam+delta,phi)[1]-F(lam,phi)[1])/delta
        xp=(F(lam,phi+delta)[0]-F(lam,phi)[0])/delta
        yp=(F(lam,phi+delta)[1]-F(lam,phi)[1])/delta
    if ellip:
        rho=a*(1-e2)/W(phi)**3; nu=a*math.cos(phi)/W(phi)
    else:
        rho=a; nu=a*math.cos(phi)
    h=math.hypot(xp,yp)/rho
