    s=abs(xl*yp-xp*yl)/(rho*nu)
    # angles
    th_p=math.atan2(xp,yp)      # meridian angle from north
    th_l=math.atan2(xl,yl)      # parallel angle from north
    conv=math.degrees(th_p)     # convergence?
    theta=90.0-math.degrees(th_p)+math.degrees(th_l)
    w=math.degrees(math.asin(abs(math.sin(th_p-th_l))))
    # tissot
    ap=(h+k)/2; ab=math.sqrt(abs(h*h-k*k))/2
    am=math.hypot(ap,ab) if False else None
    return h,k,s,theta,conv,w,ap+ab,ap-ab
def getobs(proj,l,ph,extra=[]):
    out,err=run(["+proj="+proj]+extra+["-V"], "%s %s\n"%(l,ph))
