/* pj_core.c : parameter handling, ellipsoid setup, error reporting */
#include "proj.h"

typedef struct param { char *key, *val; int used; struct param *next; } PARAM;

static PARAM *params_head = NULL;
static PARAM *params_tail = NULL;

void pj_params_clear(void){ PARAM *p=params_head; while(p){ PARAM *n=p->next; free(p->key); free(p->val); free(p); p=n;} params_head=params_tail=NULL; }

void pj_param_add(const char *key, const char *val){
    PARAM *p;
    /* dedupe: first wins */
    for(p=params_head;p;p=p->next) if(!strcmp(p->key,key)) return;
    p=(PARAM*)malloc(sizeof(PARAM));
    p->key=strdup(key); p->val=val?strdup(val):NULL; p->used=0; p->next=NULL;
    if(params_tail) params_tail->next=p; else params_head=p;
    params_tail=p;
}
void pj_param_move_front(const char *key){
    PARAM *p=params_head,*prev=NULL;
    while(p){ if(!strcmp(p->key,key)) break; prev=p; p=p->next; }
    if(p&&prev){ prev->next=p->next; if(params_tail==p) params_tail=prev; p->next=params_head; params_head=p; }
}
PARAM *pj_param_find(const char *key){ PARAM *p; for(p=params_head;p;p=p->next) if(!strcmp(p->key,key)) return p; return NULL; }

static PARAM *pj_param_get(const char *key){
    PARAM *p=pj_param_find(key);
    if(p) p->used=1;
    return p;
}
/* numeric parameter: returns 1 if found and valid */
int pj_param_d(const char *key, double *val){
    PARAM *p=pj_param_get(key);
    char *end;
    if(!p||!p->val) return 0;
    *val=strtod(p->val,&end);
    if(end==p->val||*end) return 0;   /* invalid -> treated as absent */
    return 1;
}
int pj_param_s(const char *key, const char **val){
    PARAM *p=pj_param_get(key);
    if(!p||!p->val||!*p->val) return 0;
    *val=p->val; return 1;
}
int pj_param_i(const char *key, int *val){
    double d;
    if(!pj_param_d(key,&d)) return 0;
    *val=(int)d; return 1;
}
int pj_param_flag(const char *key){ PARAM *p=pj_param_get(key); return p?1:0; }

/* report unused params */
void pj_unused_report(FILE *out){
    PARAM *p; int n=0;
    for(p=params_head;p;p=p->next) if(!p->used) n++;
    if(!n) return;
    fprintf(out,"#--- following specified but NOT used\n");
    for(p=params_head;p;p=p->next) if(!p->used) fprintf(out,"# +%s%s%s\n",p->key,p->val?"=":"",p->val?p->val:"");
}

/* error handling */
static int errcode = ERR_UNPARSEABLE;
static char errdetail[512] = "";

void pj_seterr(int code, const char *detail){ errcode=code; strncpy(errdetail,detail?detail:"",sizeof(errdetail)-1); errdetail[sizeof(errdetail)-1]=0; }
int pj_errcode(void){ return errcode; }
const char *pj_errdetail(void){ return errdetail; }
const char *pj_errstr(int code){
    switch(code){
    case ERR_MISSING_ARG: return "Missing argument";
    case ERR_INVALID_ARG: return "Invalid value for an argument";
    default: { static char buf[64]; snprintf(buf,sizeof(buf),"Unknown error (code %d)",code); return buf; }
    }
}
EOF
echo ok"}

