static void emprint(const char *msg){
    fprintf(stderr,"%s\n",RELEASE);
    fprintf(stderr,"<%s>: \n%s\n",argv0,msg?msg:"");
}
static void emprint2(const char *msg){
    fprintf(stderr,"%s\n",RELEASE);
    fprintf(stderr,"<%s>: \n%s\n",argv0,msg?msg:"");
}
