}

/* ---------------- params ---------------- */
#include "pj_core.c"

/* ---------------- math ---------------- */
static double sq(double x){ return x*x; }
/* Mercator isometric latitude (numerically stable) */
static double psi_f(double phi,double e){
    double s=sin(phi);
    return asinh(tan(phi)) - e*atanh(e*s);
}
/* invert the isometric latitude by fixed point on t=tan(pi/4+phi/2) */
static double psi_inv(double psi,double e){
    double t = exp(psi);          /* spherical guess */
    double s;
    int i;
    if (fabs(e)<EPS) { double phi = 2.0*atan(t)-HALFPI; return phi; }
    s = (t*t-1.0)/(t*t+1.0);
    for(i=0;i<30;++i){
        double tn = exp(psi)*pow((1.0+e*s)/(1.0-e*s),0.5*e);
        if (!isfinite(tn)) break;
        s = (tn*tn-1.0)/(tn*tn+1.0);
        t = tn;
        if (fabs(tn-t) < 1e-16) break;
    }
    return asin(s);
}
/* authalic q/2 */
static double qsfn(double phi,double es){
    double s=sin(phi);
    if (es<EPS) return s;
    return (1.0-es)*( s/(1.0-es*s*s) + atanh(sqrt(es)*s)/sqrt(es) );
}
static double qsfn_inv(double az,double es){
    double phi=asin(az); int i;
    if (es<EPS) return phi;
    for(i=0;i<40;++i){
        double s=sin(phi), c=cos(phi);
        double W=1.0-es*s*s;
        double q=qsfn(phi,es);
        double dq=(1.0-es)*c*(1.0)/(W*W);   /* d(q/2)/dphi = (1-es)*cos/W^4 ; approximate */
        double delta=(az-q)/( (1.0-es)*c*(W*W+es*s*s)/(W*W*W*W) );
        phi += delta;
        if (fabs(delta)<1e-15) break;
    }
    return phi;
}
/* meridian arc */
static double meridian(double phi,double es){
    double e4=es*es,e6=es*es*es;
    double c1=1.0-es/4-3.0*e4/64-5.0*e6/256;
    double c2=3.0*es/8+3.0*e4/32+45.0*e6/1024;
    double c3=15.0*e4/256+45.0*e6/1024;
    double c4=35.0*e6/3072;
    return c1*phi - c2*sin(2.0*phi) + c3*sin(4.0*phi) - c4*sin(6.0*phi);
}
static double msfn(double sinphi,double cosphi,double es){ return cosphi/sqrt(1.0-es*sinphi*sinphi); }
static double Wof(double phi,double es){ double s=sin(phi); return sqrt(1.0-es*s*s); }
/* conformal sphere radius */
static double cradius(double a,double es){ return a*sqrt(1.0-es)*(1.0+es*es/6.0); }

/* ---------------- ellipsoid setup ---------------- */
static int ellipsoid_setup(PJ *P){
    double R,a,b,rf,f,es,e;
    const char *name;
    P->es=0; P->a=0; P->b=0; P->e=0;
    if (pj_param_d("R",&R)) {
        P->a=R; P->es=0; P->e=0; P->b=R; P->ra=R;
        return 0;
    }
