        else if (pj_param_d("rf",&rf)) { if(rf<=0){pj_seterr(ERR_INVALID_ARG,"pj_init_ctx: Invalid value for rf");return -1;} P->es=2.0/rf-1.0/(rf*rf); }
        else if (pj_param_d("f",&f)) { P->es=2.0*f-f*f; }
        else if (pj_param_d("es",&es)) { P->es=es; }
        else if (pj_param_d("e",&e)) { P->es=e*e; }
        else P->es=0;
        if (P->es>0.9999999999) {pj_seterr(ERR_INVALID_ARG,"pj_init_ctx: Invalid eccentricity");return -1;}
        P->e=sqrt(P->es);
        P->b=a*sqrt(1.0-P->es);
        P->ra=a*sqrt(1.0-P->es)*(1.0+P->es*P->es/6.0);
        return 0;
    }
    if (pj_param_s("ellps",&name)) {
        int i;
        for(i=0;i<(int)(sizeof(pj_ellps)/sizeof(pj_ellps[0]));++i){
            if(!strcmp(pj_ellps[i].id,name)){
                const char *m=pj_ellps[i].major, *sh=pj_ellps[i].ell;
                char key[32]; const char *v; char *cp;
                /* parse "a=..." or "b=..." */
                strncpy(key,m,sizeof(key)-1); key[sizeof(key)-1]=0;
                cp=strchr(key,'='); if(cp){*cp=0; v=cp+1;} else v="";
                P->a=atof(v);
                if(!strcmp(key,"b")){ P->b=P->a; P->es=1.0-(P->a*P->a)/(P->a*P->a); }
                strncpy(key,sh,sizeof(key)-1); key[sizeof(key)-1]=0;
                cp=strchr(key,'='); if(cp){*cp=0; v=cp+1;} else v="";
                if(!strcmp(key,"rf")) P->es=2.0/atof(v)-1.0/(atof(v)*atof(v));
                else if(!strcmp(key,"b")) P->es=1.0-(atof(v)*atof(v))/(P->a*P->a);
                P->e=sqrt(P->es); P->b=P->a*sqrt(1.0-P->es);
                P->ra=P->a*sqrt(1.0-P->es)*(1.0+P->es*P->es/6.0);
                return 0;
            }
        }
        pj_seterr(ERR_INVALID_ARG,"pj_init_ctx: Must specify ellipsoid or sphere");
        return -1;
    }
    pj_seterr(ERR_MISSING_ARG,"pj_init_ctx: Must specify ellipsoid or sphere");
    return -1;
}

/* ---------------- datum handling ---------------- */
typedef struct { const char *id; const char *ellps; const char *extra; } PJ_DATUM;
static const PJ_DATUM pj_datums[] = {
 {"WGS84","ellps=WGS84","towgs84=0,0,0"},
 {"NAD83","ellps=GRS80","towgs84=0,0,0"},
 {"GGRS87","ellps=GRS80","towgs84=-199.87,74.79,246.62"},
 {"NAD27","ellps=clrk66","nadgrids=@conus,@alaska,@ntv2_0.gsb,@ntv1_can.dat"},
 {"OSGB36","ellps=airy","towgs84=446.448,-125.157,542.060,0.1502,0.2470,0.8421,-20.4894"},
 {"potsdam","ellps=bessel","nadgrids=@BETA2007.gsb"},
 {"carthage","ellps=clrk80ign","towgs84=-263.0,6.0,431.0"},
};
/* ellipsoid entries referenced by datums must exist: add aliases */
static const PJ_ELLPS pj_ellps_extra[] = {
 {"WGS84","a=6378137.0","rf=298.257223563","WGS 1984"},
};

static int datum_setup(void){
    const char *d; size_t i,j;
    if(!pj_param_s("datum",&d)) return 0;
    for(i=0;i<sizeof(pj_datums)/sizeof(pj_datums[0]);++i){
        if(!strcmp(pj_datums[i].id,d)){
            char buf[256]; const char *p=pj_datums[i].ellps;
            /* add ellps=... and extra params, marking them */
            while(*p){
                const char *sp=strchr(p,' ');
                size_t n=sp?(size_t)(sp-p):strlen(p);
                if(n>=sizeof(buf)) n=sizeof(buf)-1;
                memcpy(buf,p,n); buf[n]=0;
                { char *eq=strchr(buf,'=');
                  if(eq){ *eq=0; pj_param_add(buf,eq+1);} else pj_param_add(buf,NULL);}
                p = sp? sp+1 : p+strlen(p);
            }
            p=pj_datums[i].extra;
            while(*p){
                const char *sp=strchr(p,' ');
                size_t n=sp?(size_t)(sp-p):strlen(p);
                if(n>=sizeof(buf)) n=sizeof(buf)-1;
                memcpy(buf,p,n); buf[n]=0;
                { char *eq=strchr(buf,'=');
                  if(eq){ *eq=0; pj_param_add(buf,eq+1);} else pj_param_add(buf,NULL);}
                p = sp? sp+1 : p+strlen(p);
            }
            return 0;
        }
    }
    pj_seterr(ERR_INVALID_ARG,"Unknown value for datum");
    return -1;
}

/* ---------------- units ---------------- */
static int units_setup(PJ *P){
    const char *u; size_t i;
    if(!pj_param_s("units",&u)) return 0;
    for(i=0;i<sizeof(pj_units)/sizeof(pj_units[0]);++i){
        if(!strcmp(pj_units[i].id,u)){ P->to_meter=1.0; return 0; }
    }
    { double d; char *end; d=strtod(u,&end); if(end!=u && !*end){ return 0; } }
    pj_seterr(ERR_INVALID_ARG,"Invalid value for units");
    return -1;
}

/* ---------------- projections ---------------- */
/* Mercator */
static int merc_setup(PJ *P){
    double ts;
    if (pj_param_d("lat_ts",&ts)) P->k0=msfn(sin(ts*DEG_TO_RAD),cos(ts*DEG_TO_RAD),P->es);
    else P->k0=1.0;
    if (P->k0<=0){pj_seterr(ERR_INVALID_ARG,"merc: Invalid value for lat_ts");return -1;}
    return 0;
}
static int merc_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->k0*P->a*lam;
    *y=P->k0*P->a*psi_f(phi,P->e);
    return 0;
}
static int merc_inv(PJ *P,double x,double y,double *lam,double *phi){
    double p=y/(P->k0*P->a);
    *lam=x/(P->k0*P->a);
    if (fabs(*lam)>M_PI) { if(!P->over) { *lam = *lam - 2*M_PI*floor((*lam+M_PI)/(2*M_PI)); } }
    *phi=psi_inv(p,P->e);
    if (fabs(*phi)>HALFPI) return 1;
    return 0;
}
/* Web Mercator */
static int webmerc_setup(PJ *P){ P->k0=1.0; return 0; }
static int webmerc_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->a*lam; *y=P->a*asinh(tan(phi)); return 0;
}
static int webmerc_inv(PJ *P,double x,double y,double *lam,double *phi){
    *lam=x/P->a;
    *phi=2.0*atan(exp(y/P->a))-HALFPI;
    if(fabs(*phi)>HALFPI) return 1;
    return 0;
}
/* Equal area cylindrical (cea) */
static int cea_setup(PJ *P){
    double ts;
    if (pj_param_d("lat_ts",&ts)) P->k0=msfn(sin(ts*DEG_TO_RAD),cos(ts*DEG_TO_RAD),P->es);
    else P->k0=1.0;
    return 0;
}
static int cea_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->k0*P->a*lam; *y=P->a*qsfn(phi,P->es)/P->k0; return 0;
}
static int cea_inv(PJ *P,double x,double y,double *lam,double *phi){
    double az=y*P->k0/P->a;
    *lam=x/(P->k0*P->a);
    *phi=qsfn_inv(az,P->es);
    if(fabs(*phi)>HALFPI) return 1;
    return 0;
}
/* Equidistant cylindrical (eqc) */
static int eqc_setup(PJ *P){ double d; if(!pj_param_d("lat_0",&d)) P->phi0=0; else P->phi0=d*DEG_TO_RAD; P->k0=1.0; return 0; }
static int eqc_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->a*lam; *y=P->a*(meridian(phi,P->es)-meridian(P->phi0,P->es)); return 0;
}
static int eqc_inv(PJ *P,double x,double y,double *lam,double *phi){
    double m=y/P->a+meridian(P->phi0,P->es);
    *lam=x/P->a;
    /* invert meridian arc by Newton iteration */
    double p=m/P->a;
    *phi=p; { int i; for(i=0;i<30;++i){ double s=sin(*phi),c=cos(*phi); double W=1.0-P->es*s*s;
        double M=meridian(*phi,P->es)/P->a;
        double dM=(1.0-P->es)/(W*sqrt(W));
        double d=(p-M)/dM; *phi+=d; if(fabs(d)<1e-15) break; } }
    if(fabs(*phi)>HALFPI) return 1;
    return 0;
}
/* Miller cylindrical (spherical) */
static int mill_setup(PJ *P){ P->k0=1.0; return 0; }
static int mill_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->a*lam; *y=1.25*P->a*asinh(sin(0.4*phi)); return 0;
}
static int mill_inv(PJ *P,double x,double y,double *lam,double *phi){
    double t=exp(y/(1.25*P->a));
    double s=(t*t-1.0)/(t*t+1.0);
    *phi=asin(s)/0.4; *lam=x/P->a;
    if(fabs(*phi)>HALFPI) return 1;
    return 0;
}
/* Sinusoidal */
static int sinu_setup(PJ *P){ P->k0=1.0; return 0; }
static int sinu_fwd(PJ *P,double lam,double phi,double *x,double *y){
    if (fabs(phi)>HALFPI) return 1;
    *x=P->a*lam*cos(phi)/Wof(phi,P->es);
    *y=P->a*meridian(phi,P->es); return 0;
}
static int sinu_inv(PJ *P,double x,double y,double *lam,double *phi){
    double m=y/P->a;
    *phi=m; { int i; for(i=0;i<40;++i){ double s=sin(*phi),c=cos(*phi); double W=1.0-P->es*s*s;
        double M=meridian(*phi,P->es)/P->a;
        double dM=(1.0-P->es)/(W*sqrt(W));
        double d=(m-M)/dM; *phi+=d; if(fabs(d)<1e-15) break; } }
    if(fabs(*phi)>HALFPI) return 1;
    *lam=x*Wof(*phi,P->es)/(P->a*cos(*phi));
    if(fabs(*lam)>M_PI) *lam = *lam - 2*M_PI*floor((*lam+M_PI)/(2*M_PI));
    return 0;
}
/* Transverse Mercator (ellipsoidal) */
static int tmerc_setup(PJ *P){
    double d;
    if(!pj_param_d("k_0",&d)) P->k0=1.0; else P->k0=d;
    if (P->k0<=0){ pj_seterr(ERR_INVALID_ARG,"tmerc: Invalid value for k/k_0: it should be > 0"); return -1; }
    return 0;
}
/* conformal coordinates on the transverse Mercator sphere */
static void tm_conformal(PJ *P,double lam,double phi,double *chi,double *lamc){
    double s=sin(phi),c=cos(phi),es=P->es,e=P->e;
    double t=asinh(c*sin(lam)/sqrt(1.0-es*c*c)) ; /* isometric in transverse frame */
    double t2=e*atanh(e*c*cos(lam)/sqrt(1.0-es*c*c));
    *chi=0.0; (void)t2;
    /* standard: conformal latitude of transverse Mercator */
    { double bl=sqrt(1.0-es*c*c);
      double tn=bl*c*sin(lam);
      *chi=asinh(tn);  /* approximate */
    }
}
static int tmerc_fwd(PJ *P,double lam,double phi,double *x,double *y){
