/* UTM */
static int utm_setup(PJ *P){
    const char *zv; double zone=0; int south=0; double d;
    P->k0=0.9996; P->x0=500000.0;
    if (pj_param_s("zone",&zv)){
        char *end; zone=strtod(zv,&end);
