        if (*end=='s'||*end=='S') south=1;
        else if (*end=='n'||*end=='N') south=0;
        else if (*end) { pj_seterr(ERR_INVALID_ARG,"utm: Invalid value for zone"); return -1; }
        P->lam0=(6.0*zone-183.0)*DEG_TO_RAD;
        if (south) P->y0=10000000.0;
    } else {
        /* automatic zone from the first input coordinate is not possible here */
        pj_seterr(ERR_INVALID_ARG,"utm: Invalid value for zone"); return -1;
    }
    if(!pj_param_d("k_0",&d)) ; else P->k0=d;
    return 0;
}
