/* ---------------- params ---------------- */
#include "pj_core.c"

/* ---------------- math ---------------- */
static double sq(double x){ return x*x; }
/* Mercator isometric latitude (numerically stable) */
static double psi_f(double phi,double e){
    double s=sin(phi);
    return asinh(tan(phi)) - e*atanh(e*s);
}
/* invert the isometric latitude by fixed point on t=tan(pi/4+phi/2) */
static double psi_inv(double psi,double e){
    double t = exp(psi);          /* spherical guess */
    double s;
    int i;
    if (fabs(e)<EPS) { double phi = 2.0*atan(t)-HALFPI; return phi; }
    s = (t*t-1.0)/(t*t+1.0);
    for(i=0;i<30;++i){
        double tn = exp(psi)*pow((1.0+e*s)/(1.0-e*s),0.5*e);
        if (!isfinite(tn)) break;
        s = (tn*tn-1.0)/(tn*tn+1.0);
        t = tn;
        if (fabs(tn-t) < 1e-16) break;
    }
    return asin(s);
}
/* authalic q/2 */
static double qsfn(double phi,double es){
    double s=sin(phi);
    if (es<EPS) return s;
    return (1.0-es)*( s/(1.0-es*s*s) + atanh(sqrt(es)*s)/sqrt(es) );
