static double qsfn_inv(double az,double es){
    double phi=asin(az); int i;
    if (es<EPS) return phi;
    for(i=0;i<40;++i){
        double s=sin(phi), c=cos(phi);
        double W=1.0-es*s*s;
        double q=qsfn(phi,es);
        double dq=(1.0-es)*c*(1.0)/(W*W);   /* d(q/2)/dphi = (1-es)*cos/W^4 ; approximate */
        double delta=(az-q)/( (1.0-es)*c*(W*W+es*s*s)/(W*W*W*W) );
