    double c2=3.0*es/8+3.0*e4/32+45.0*e6/1024;
    double c3=15.0*e4/256+45.0*e6/1024;
    double c4=35.0*e6/3072;
    return c1*phi - c2*sin(2.0*phi) + c3*sin(4.0*phi) - c4*sin(6.0*phi);
