        int i;
        for(i=0;i<(int)(sizeof(pj_ellps)/sizeof(pj_ellps[0]));++i){
            if(!strcmp(pj_ellps[i].id,name)){
                const char *m=pj_ellps[i].major, *sh=pj_ellps[i].ell;
                char key[32]; const char *v; char *cp;
                /* parse "a=..." or "b=..." */
                strncpy(key,m,sizeof(key)-1); key[sizeof(key)-1]=0;
                cp=strchr(key,'='); if(cp){*cp=0; v=cp+1;} else v="";
                P->a=atof(v);
                if(!strcmp(key,"b")){ P->b=P->a; P->es=1.0-(P->a*P->a)/(P->a*P->a); }
                strncpy(key,sh,sizeof(key)-1); key[sizeof(key)-1]=0;
